from collections import Counter
import re, unittest

def top_k_words(text, k):
    words = re.findall(r"[a-z0-9']+", text.lower())
    counts = Counter(words)
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return [w for w, _ in ranked[:k]]

class TestTopK(unittest.TestCase):
    def test_counts(self): self.assertEqual(top_k_words('b a a b c', 1), ['a'])
    def test_ties(self): self.assertEqual(top_k_words('b a', 2), ['a', 'b'])
    def test_empty(self): self.assertEqual(top_k_words('', 3), [])
    def test_k_large(self): self.assertEqual(top_k_words('x', 5), ['x'])

